def initials(name):
    # Split by whitespace and filter out empty strings
    words = [word for word in name.split() if word]

    # Check if any word contains a hyphen
    has_hyphen = any('-' in word for word in words)

    # Extract initials from each word
    initials_list = []
    for word in words:
        # Handle hyphenated names
        if '-' in word:
            parts = word.split('-')
            for part in parts:
                initials_list.append(part[0].upper())
        else:
            initials_list.append(word[0].upper())

    # Determine the output format based on hyphen
    if has_hyphen:
        # Hyphenated names: use periods between initials
        result = '.'.join(initials_list) + '.'
    else:
        # Non-hyphenated names: no periods
        result = ''.join(initials_list)

    return result

