def safe_div(a, b):
    # Handle None inputs
    if a is None or b is None:
        return None

    # Convert inputs to numbers if they are strings
    try:
        a = float(a) if isinstance(a, str) else a
        b = float(b) if isinstance(b, str) else b
    except (ValueError, TypeError):
        return None

    # Check for division by zero
    if b == 0:
        return None

    # Perform division
    result = a / b

    # If result is a whole number, return as int
    if result.is_integer():
        return int(result)
    else:
        return float(result)

