def dedupe(xs):
    if not xs:
        return []

    result = []
    seen = set()
    for x in xs:
        if isinstance(x, str):
            key = x.lower()
            if key not in seen:
                result.append(x)
                seen.add(key)
        else:
            # For non-strings, just add them (no deduplication)
            result.append(x)

    # Reverse the result
    return list(reversed(result))

