    current_word = []

    def process_word(word):
        if not word:
            return word
        # Split by hyphen
        parts = word.split('-')
        processed = []
        for part in parts:
            if len(part) == 1:
                # Single letter word stays lowercase
                processed.append(part.lower())
            else:
                # Multi-letter word: capitalize first letter, lowercase the rest
                processed.append(part[0].upper() + part[1:].lower())
        return '-'.join(processed)

    for char in s:
        if char == ' ':
            if current_word:
                result.append(process_word(''.join(current_word)))
                current_word = []
            result.append(char)
        elif char == '-':
            current_word.append(char)
        else:
            current_word.append(char)

    # Process last word if any
    if current_word:
        result.append(process_word(''.join(current_word)))

    return ''.join(result)

def median(xs):
    # Filter out None values
    filtered = [x for x in xs if x is not None]

    # Empty list after filtering
    if len(filtered) == 0:
        return None

    n = len(filtered)

    if n % 2 == 1:
        # Odd length: return lower middle value
        return filtered[n // 2 - 1]
    else:
        # Even length: return higher middle value
        return filtered[n // 2]

def count_vowels(s):
    vowels = set('aeiouAEIOU')
    count = 0
    for char in s:
        if char in vowels:
            count += 1
    return count

def to_snake(name):
    if not name:
        return name

    # If already all lowercase, return as is
    if name.islower():
        return name

    result = []
    current_word = []

    i = 0
    while i < len(name):
        char = name[i]

        if char.isdigit():
            current_word.append(char)
        elif char.isupper():
            # If current_word is not empty and the last character was lowercase or digit,
            # we need to end the current word and start a new one
            if current_word and (current_word[-1].islower() or current_word[-1].isdigit()):
                result.append(''.join(current_word))
                current_word = []
            # Start a new word with this uppercase letter
            current_word = [char]
        elif char.islower():
            current_word.append(char)

        i += 1

    # Don't forget the last word
    if current_word:
        result.append(''.join(current_word))

    return '_'.join(result)

