        words_list = result[length]
        if len(words_list) > 1:
            # Sort by original index
            indexed = [(i, words_list[i]) for i in range(len(words_list))]
            indexed.sort(key=lambda x: x[0])
            result[length] = [w for _, w in indexed]

    # Convert single-word groups to the word itself
