def group_by_len(words):
    result = {}
    for word in words:
        length = len(word.strip())
        if length not in result:
            if length == 1:
                result[length] = word
            else:
                result[length] = [word]
        else:
            if isinstance(result[length], list):
                result[length].append(word)
            else:
                result[length] = [result[length], word]
    return result

